contract BridgeStone is Ownable, IERC721Receiver
{
    struct RecycleTokenInfo
    {
        uint256 TokenID;
        uint64 MemeberId;
        uint64 Time;
        address User;
    }

    RecycleTokenInfo[] private _RecycleTokens;

    IERC721 private _StroneContract;

    constructor(address stroneAddress)
    {
        SetStroneContractAddress(stroneAddress);
    }

    function SetStroneContractAddress(address stroneAddress) public onlyOwner
    {
        _StroneContract = IERC721(stroneAddress);
    }
    function RecycleStone(uint256[] calldata tokenIds, uint64 memeberId) public 
    {
        for(uint256 i = 0 ; i < tokenIds.length; i++)
        {
            require(_StroneContract.ownerOf(tokenIds[i]) == msg.sender , "not owner token");
            require( _StroneContract.getApproved(tokenIds[i]) == address(this) || _StroneContract.isApprovedForAll(msg.sender, address(this)) , "not approved token");
            _StroneContract.safeTransferFrom(msg.sender, address(this), tokenIds[i]);

            _RecycleTokens.push(RecycleTokenInfo(
                {
                    TokenID: tokenIds[i],
                    MemeberId: memeberId,
                    Time: uint64(block.timestamp),
                    User: msg.sender
                }));
        }
    }
    function GetRecycleLength() public onlyOwner view returns(uint256)
    {
        return _RecycleTokens.length;
    }
    function GetRecycleTokenInfo(uint256 index) onlyOwner public view returns(RecycleTokenInfo memory)
    {
         return _RecycleTokens[index];
    }
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data) 
        external pure returns (bytes4)
    {
        return IERC721Receiver.onERC721Received.selector;
    }
}

